import assert from "node:assert/strict";
import test from "node:test";
import { loadModule, plain } from "./runtime.mjs";

/** Creates the real plugin repository with an independent first-install identity counter. */
function repository() {
  const { RepositorySession } = loadModule("src/repository.ts");
  const { createInitialState } = loadModule("src/storage/state.ts");
  const state = createInitialState(1);
  return { state, session: new RepositorySession(state, "identity-test") };
}

/** Verifies the UUID format generated by the plugin for named synchronized records. */
function assertUuid(id) {
  assert.match(id, /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/);
}

/** Independent devices must not reuse the same character, group, tag or library counter identity. */
test("independent repositories allocate UUIDs for all named records", async () => {
  const { createCharacterDraft, createGroupDraft, createTagDraft } = loadModule("src/drafts.ts");
  const first = repository(), second = repository();
  const identities = [];
  for (const { state, session } of [first, second]) {
    const card = await session.createCharacter({ ...plain(createCharacterDraft()), name: "Same role" });
    const group = await session.createGroup({ ...plain(createGroupDraft()), name: "Same group" });
    const tag = await session.createTag({ ...plain(createTagDraft()), name: "Same tag" });
    const store = await session.createStore("Same library");
    for (const record of [card, group, tag, store]) { assertUuid(record.id); identities.push(record.id); }
    assert.equal(state.version, 1);
    assertUuid(state.cards[0].id); identities.push(state.cards[0].id);
    assert.ok(state.owners.some(owner => owner.ownerKey === "character:" + card.id));
    assert.ok(state.owners.some(owner => owner.ownerKey === "shared:" + store.id));
    const renamed = await session.updateCharacter({ ...card, name: "Renamed" });
    assert.equal(renamed.id, card.id);
  }
  assert.equal(new Set(identities).size, identities.length);
});
